def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    color = min((v for v in counts if v not in (0,)), key=lambda v: counts[v])
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == color]
    min_r = min(r for r, c in points); min_c = min(c for r, c in points)
    shape = {(r-min_r, c-min_c) for r, c in points}
    dh = max(r for r, c in shape); dw = max(c for r, c in shape)
    out = [row[:] for row in grid]
    background = min((v for v in counts if v != color), key=lambda v: counts[v])
    for y in range(h-dh):
        for x in range(w-dw):
            if all(grid[y+dy][x+dx] == 0 for dy, dx in shape):
